#include <bits/stdc++.h>
using namespace std;

int longestOnes(vector<int>& nums, int k) {
    int zeros = 0, start = 0, ans = 0;
    for (int i = 0; i < (int)nums.size(); ++i) {
        zeros += nums[i] == 0;
        while (zeros > k) {
            zeros -= nums[start] == 0;
            ++start;
        }
        ans = max(ans, i - start + 1);
    }
    return ans;
}

