class Solution {
    public int longestOnes(int[] nums, int k) {
        int start = 0, zeros = 0, best = 0;
        for (int i = 0; i < nums.length; ++i) {
            if (nums[i] == 0) ++zeros;
            while (zeros > k) {
                if (nums[start] == 0) --zeros;
                ++start;
            }
            best = Math.max(best, i - start + 1);
        }
        return best;
    }
}
